<script setup lang="ts">
import{computed,onUnmounted,ref}from'vue';
import DOMPurify from'dompurify';
import{safeSources,type Source}from'../services/api';
import MarkdownContent from'./MarkdownContent.vue';
defineProps<{disabled?:boolean}>();const emit=defineEmits<{insert:[value:string]}>();
const query=ref(''),file=ref<File|null>(null),preview=ref(''),busy=ref(false),error=ref(''),reply=ref<{content:string;provider:string;model:string;sources:Source[];suggestions?:string}|null>(null);let controller:AbortController|undefined,disposed=false;
const suggestions=computed(()=>reply.value?.suggestions?DOMPurify.sanitize(reply.value.suggestions,{USE_PROFILES:{html:true,svg:true},FORBID_TAGS:['script','iframe','object','embed','form','input','video','audio'],FORBID_ATTR:['onload','onclick']}):'');
function clear(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';file.value=null;}
function choose(event:Event){error.value='';clear();const value=(event.target as HTMLInputElement).files?.[0];if(!value)return;if(!['image/png','image/jpeg','image/webp'].includes(value.type)||value.size>4*1024*1024){error.value='Usa PNG, JPEG o WebP de hasta 4 MB.';return;}file.value=value;preview.value=URL.createObjectURL(value);}
function base64(value:File){return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]??'');reader.onerror=()=>reject(new Error('No se pudo leer la imagen.'));reader.readAsDataURL(value);});}
async function research(mode:'web'|'image'){
 if(mode==='image'&&!file.value)return;busy.value=true;error.value='';reply.value=null;controller=new AbortController();
 try{const body=mode==='web'?{mode,query:query.value}:{mode,query:query.value||'Analiza esta captura para ayudarme con el proyecto. Explica lo visible, posibles problemas y próximos pasos.',image:{mimeType:file.value!.type,data:await base64(file.value!)}};
 const response=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error?.message??'No se pudo completar la investigación.');if(!result||typeof result.content!=='string'||result.provider!=='gemini'||typeof result.model!=='string')throw new Error('Respuesta de investigación inválida.');if(!disposed)reply.value={content:result.content,provider:result.provider,model:result.model,sources:safeSources(result.sources),...(typeof result.suggestions==='string'?{suggestions:result.suggestions}:{})};
 }catch(cause){if(!disposed)error.value=(cause as Error).message;}finally{busy.value=false;controller=undefined;}
}
function insert(){if(reply.value)emit('insert',`Resultado de investigación revisado por el usuario (${reply.value.provider} / ${reply.value.model}):\n${reply.value.content}\n${reply.value.sources.map(source=>`${source.title}: ${source.uri}`).join('\n')}`);}
onUnmounted(()=>{disposed=true;controller?.abort();clear();});
</script>
<template><details class="research-panel"><summary>Imágenes y búsqueda web</summary><p class="result-note">Gemini analiza la imagen seleccionada o consulta Google Search. Estas acciones consumen su cuota. El resultado aparece aquí para revisarlo antes de usarlo en el chat; la aplicación no guarda el archivo de imagen.</p><label for="research-query">Consulta para imagen o búsqueda web</label><textarea id="research-query" v-model="query" rows="2" maxlength="3000" :disabled="busy||disabled" placeholder="Describe lo que quieres investigar…"/><label for="research-image">Imagen PNG, JPEG o WebP, hasta 4 MB</label><input id="research-image" type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy||disabled" @change="choose"/><div v-if="file" class="image-preview"><img :src="preview" alt="Imagen seleccionada para analizar"/><p>{{ file.name }} · {{ (file.size/1024).toFixed(1) }} KB</p><button type="button" class="connection-action" :disabled="busy||disabled" @click="clear">Retirar imagen</button></div><div class="source-actions"><button type="button" class="connection-action" :disabled="busy||disabled||!file" @click="research('image')">Analizar imagen con Gemini</button><button type="button" class="connection-action" :disabled="busy||disabled||!query.trim()" @click="research('web')">Buscar con Gemini</button></div><p v-if="busy" role="status">Investigando con Gemini…</p><p v-if="error" role="alert" class="library-error">{{ error }}</p><section v-if="reply" aria-label="Resultado de investigación"><p class="response-provider">{{ reply.provider.toUpperCase() }} · {{ reply.model }}</p><MarkdownContent :content="reply.content"/><div class="sources"><a v-for="source in reply.sources" :key="source.uri" :href="source.uri" target="_blank" rel="noopener noreferrer">{{ source.title }} ↗</a></div><iframe v-if="suggestions" :srcdoc="suggestions" title="Sugerencias de Google Search" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer"></iframe><button type="button" class="connection-action" :disabled="disabled||busy" @click="insert">Usar resultado en mensaje</button></section></details></template>
<style scoped>.research-panel{border:1px solid #233a41;border-radius:8px;padding:14px;margin:12px 0;max-width:100%}.research-panel label{display:block;margin:14px 0 8px;font-size:12px}.research-panel textarea{width:100%;background:#08151a;border:1px solid #29434b;border-radius:6px;color:#dcebf0;padding:10px}.research-panel input{max-width:100%;font-size:12px}.image-preview{margin:15px 0}.image-preview img{max-width:100%;max-height:280px;object-fit:contain}.image-preview p{font-size:11px;overflow-wrap:anywhere}.research-panel iframe{width:100%;height:180px;border:0;background:white;margin:14px 0}.research-panel section{margin-top:18px}</style>
